"use strict";(self.webpackChunksayhii_portal_documentation=self.webpackChunksayhii_portal_documentation||[]).push([[849],{6164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"documentationSidebar":[{"type":"link","label":"sayhii Overview","href":"/docs/intro","docId":"intro","unlisted":false},{"type":"category","label":"sayhii Portal - Everyone","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Home","href":"/docs/portal-everyone/home","docId":"portal-everyone/home","unlisted":false},{"type":"link","label":"Profile","href":"/docs/portal-everyone/profile","docId":"portal-everyone/profile","unlisted":false},{"type":"link","label":"Reports","href":"/docs/portal-everyone/reports","docId":"portal-everyone/reports","unlisted":false}],"href":"/docs/category/sayhii-portal---everyone"},{"type":"category","label":"sayhii Portal - Admin","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Upload File","href":"/docs/portal-admin/upload-file","docId":"portal-admin/upload-file","unlisted":false},{"type":"link","label":"Custom Modules","href":"/docs/portal-admin/custom-modules","docId":"portal-admin/custom-modules","unlisted":false},{"type":"link","label":"Organization","href":"/docs/portal-admin/organization","docId":"portal-admin/organization","unlisted":false},{"type":"link","label":"Admin Dashboard","href":"/docs/portal-admin/admin-dashboard","docId":"portal-admin/admin-dashboard","unlisted":false}],"href":"/docs/category/sayhii-portal---admin"},{"type":"category","label":"sayhii Portal - Settings","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Question Plan","href":"/docs/portal-settings/question-plan","docId":"portal-settings/question-plan","unlisted":false},{"type":"link","label":"HRIS Integration","href":"/docs/portal-settings/hris-integration","docId":"portal-settings/hris-integration","unlisted":false},{"type":"link","label":"User File Management","href":"/docs/portal-settings/user-file-management","docId":"portal-settings/user-file-management","unlisted":false},{"type":"link","label":"Setup SSO","href":"/docs/portal-settings/single-sign-on","docId":"portal-settings/single-sign-on","unlisted":false}],"href":"/docs/category/sayhii-portal---settings"},{"type":"category","label":"sayhii App","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"App Features","href":"/docs/desktop/basic-functionality","docId":"desktop/basic-functionality","unlisted":false},{"type":"link","label":"macOS Details","href":"/docs/desktop/macOS-details","docId":"desktop/macOS-details","unlisted":false},{"type":"link","label":"Windows Details","href":"/docs/desktop/windows-details","docId":"desktop/windows-details","unlisted":false}],"href":"/docs/category/sayhii-app"}]},"docs":{"desktop/basic-functionality":{"id":"desktop/basic-functionality","title":"App Features","description":"The sayhii app is a desktop application designed to ask users questions.","sidebar":"documentationSidebar"},"desktop/macOS-details":{"id":"desktop/macOS-details","title":"macOS Details","description":"The macOS version of the application is distributed as a dmg file. When installing the package on a macOS machine manually, the user should mount the dmg and drag the sayhii application icon to the Apps folder. The application will then install itself as a startup application to be restarted whenever the user starts the computer.","sidebar":"documentationSidebar"},"desktop/windows-details":{"id":"desktop/windows-details","title":"Windows Details","description":"The Windows version of the App is distributed as an msi installation package. After the application is installed, the user may need to restart their computer to complete the installation and start the application as a background app.","sidebar":"documentationSidebar"},"intro":{"id":"intro","title":"sayhii Overview","description":"sayhii provides organizations with the ability to listen to employees and understand where the organization may be struggling. We\'ve seen a lot of organizations struggling to find the right balance as we move into the future of work. Things change, but the need to connect with co-workers and understand our place in an organization is going to always be there. If everything is just transactional, what motivates someone to stay committed to the goals and values of the organization. Do you even really have an organization?","sidebar":"documentationSidebar"},"portal-admin/admin-dashboard":{"id":"portal-admin/admin-dashboard","title":"Admin Dashboard","description":"The admin dashboard provides an organization wide view of the data collected by sayhii. This includes information that can help understand user participation and rollout of the application as well as analyzing responses by theme.","sidebar":"documentationSidebar"},"portal-admin/custom-modules":{"id":"portal-admin/custom-modules","title":"Custom Modules","description":"You can create your own sets of questions that sayhii will distibute to your employees. A custom module defines a set of related questions that can be tailored to your organization\'s unique needs.","sidebar":"documentationSidebar"},"portal-admin/organization":{"id":"portal-admin/organization","title":"Organization","description":"All of the sayhii users configured for your organization are listed on the organization page. You can filter this list to find specific users in the organization. You can also delete or disable individual users.","sidebar":"documentationSidebar"},"portal-admin/upload-file":{"id":"portal-admin/upload-file","title":"Upload File","description":"Do you need to share a file with sayhii that just doesn\'t feel right to email? You can upload that file through this interface. The file gets sent directly to sayhii and stored in a private cloud location.","sidebar":"documentationSidebar"},"portal-everyone/home":{"id":"portal-everyone/home","title":"Home","description":"The sayhii homepage is a focus on you. We provide a dashboard to help you understand yourself, your organization, and the way your peers are answering questions related to specific themes. This dashboard provides three focus areas:","sidebar":"documentationSidebar"},"portal-everyone/profile":{"id":"portal-everyone/profile","title":"Profile","description":"Have you ever wondered if you can \\"change your answers\\" from your original registration in sayhii? The answer is absolutely YES!","sidebar":"documentationSidebar"},"portal-everyone/reports":{"id":"portal-everyone/reports","title":"Reports","description":"Here you can download static reports that have been generated for you. This includes your past monthly activations that have previously been emailed to you.","sidebar":"documentationSidebar"},"portal-settings/hris-integration":{"id":"portal-settings/hris-integration","title":"HRIS Integration","description":"Human Resources Information Systems (HRIS) applications are frequently used for tracking employees within an organization. Some HRIS systems directly support payroll and employee actions, some are simply used for IT security implementations. In either case, these systems provide lists of employees and frequently manager and department hierarchies that can be imporant to sayhii.","sidebar":"documentationSidebar"},"portal-settings/question-plan":{"id":"portal-settings/question-plan","title":"Question Plan","description":"What types of questions are going to be asked when? Are questions even being asked? The question plan is designed to answer those questions.","sidebar":"documentationSidebar"},"portal-settings/single-sign-on":{"id":"portal-settings/single-sign-on","title":"Setup SSO","description":"Single Sign-On configuration allows sayhii to connect to your corporate identity provider. Using this connection, users are able to authenticate to the sayhii desktop app and the sayhii portal using their corporate credentials.","sidebar":"documentationSidebar"},"portal-settings/user-file-management":{"id":"portal-settings/user-file-management","title":"User File Management","description":"If you can\'t link sayhii to an HRIS, you can manage your list of users in sayhii using our file upload feature.","sidebar":"documentationSidebar"}}}}')}}]);